pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, but too large to be efficient)
    // We penalize values that are small but not zero, as they are harder to fill later.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // 2. Aggressive 2-step lookahead matching
    // If the next item fits perfectly in the post_residual, drastically reduce the score.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Reward if post_residual can accommodate the next item perfectly
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Heuristic for new bin creation
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very tight (highly fragmented)
        // or if there are no bins that can fit the current item comfortably.
        if fitting_bins_count > 0 {
            score += 60.0; // High penalty to prevent opening new bin if others exist
        } else {
            score -= 10.0; // Preference to open if no other choice
        }
    }

    // 4. Global state awareness
    // Favor packing into bins that are already "near" the average fullness to keep distribution uniform.
    let current_bin_fullness = (bin_capacity - bin_residual) as f64;
    score += (current_bin_fullness - mean_residual).abs() * 0.2;

    // 5. Progression scaling
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (1.0 - progress) * 20.0;
    }

    score
}

