    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize small residuals that are likely to become stranded ("dead space").
    let mut score = post_res + (1.0 / (post_res + 0.1));

    // Non-linear coupling: As the stream progresses, prioritize tighter fits.
    // If we are near the end of the stream, prioritize clearing current bins.
    let tightness_penalty = (1.0 - progress) * post_res.powf(1.5);
    score += tightness_penalty;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Heuristic for new bin creation:
    // If bin_residual == bin_capacity, we are evaluating a "New Bin".
    // We only want to open a new bin if the current open bins are "too full" 
    // to accommodate future items effectively.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream.
        // We only open a new bin if the average residual of existing bins is already very low.
        score = 40.0 + (progress * 60.0) + (mean_residual * 0.5);
    } else {
        // If it's a fitting bin, penalize bins that are "almost full" but 
        // leave an awkward gap that won't fit future items.
        if post_res < 10.0 && post_res > 0.0 {
            score += 20.0;
        }
    }

    score
}

