pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: penalize post_residuals that are small but non-zero (fragments)
    // We favor perfectly filled bins (0 residual) or larger residuals that can accommodate next items.
    if post_residual > 0 {
        score += 100.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Class Logic: Reward bins that align with typical item size clusters.
    // Items tend to be 1/2, 1/3, 1/4 of capacity.
    let mod_val = post_residual % 25;
    if mod_val == 0 {
        score -= 5.0;
    }

    // 4. Scarcity/Density Balance: If we are late in the stream, prioritize packing tightly.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Thresholding: 
    // If this is a new bin (bin_residual == capacity), penalize based on how much 
    // room is left in existing bins to prevent fragmenting.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is high (i.e., we are already failing to pack well)
        score += mean_residual * 0.5;
        // If we have very few fitting bins, opening a new one is more attractive.
        score -= (fitting_bins_count as f64) * 10.0;
    } else {
        // If it's an existing bin, reward it if it's the only one that fits the item.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" (small residuals that are hard to fill).
    // We penalize residuals < 20 more heavily as they are harder to fill.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powf(1.5);
    }

    // Lookahead logic: if the next item is large, prioritize keeping larger residuals.
    // If next_item_size is 0, we are near the end, prioritize packing tightly.
    if next_item_size > 0 {
        let next_fit_penalty = if post < next_item_size as f64 { 50.0 } else { 0.0 };
        score += next_fit_penalty * (1.0 - progress);
    }

    // If this is the last chance for this item (only one bin fits), 
    // we heavily discount the score to prefer this bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Dynamic constraint: As the stream progresses, become more aggressive 
    // about using existing bins to minimize the total count (prevent fragmentation).
    let open_bin_penalty = (open_bins_count as f64) * (progress.powf(2.0) * 10.0);
    score += open_bin_penalty;

    // If considering a new bin (bin_residual == bin_capacity), apply a threshold
    // based on the mean residual of current bins to decide if we should open it.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
        // suggesting that existing bins are too full to accommodate future items.
        score = 25.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We favor bins that result in a smaller residual (Best Fit).
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Matching (The "Tight-Fit" Reward):
    // If the next item fits perfectly into the current post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations that leave exactly enough room for the next item
        score -= (100.0 - diff) * 2.0;
    }

    // 3. Fragmentation Mitigation:
    // If post_residual is small but not zero, it is often "poisoned" (too small for most items).
    // Penalize residuals that are smaller than the smallest likely item (e.g., < 10) unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global Density Balancing:
    // If the current bin's residual is significantly higher than the mean, we are creating a "loose" bin.
    // Penalize this to force items into denser, more constrained bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty to 
    // discourage opening new bins unless the existing fit quality is abysmal.
    if bin_residual == bin_capacity {
        score += 85.0;
        // If we have very few open bins, opening a new one is slightly more acceptable.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: bias against it unless we are forced or the fit is perfect.
        // As the stream progresses, we become more conservative about opening new bins.
        score = 85.0 + (progress * 20.0);

        // If no existing bin can fit the item, we must open a new one.
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    } else {
        // Best Fit Decreasing logic: minimize post_residual (the space left over).
        // Penalty for creating a "sliver" (space too small to likely fit future items).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead heuristic: if next item exists, reward bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else if post_residual < next_item_size && post_residual >= 10 {
                // If we can't fit the next item, but the current bin has enough space to be useful for something else.
                score += 5.0;
            }
        }

        // Global state awareness: if we have many open bins, penalize moderate fits to force consolidation.
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 0.5;
        }

        // Dynamic adjustment: favor bins closer to the mean residual to maintain uniform bin fullness.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}
